import{_ as a,g as t,e as i,a4 as s}from"./chunks/framework.CEYJDsBW.js";const m=JSON.parse('{"title":"按物品组件进入对应文章","description":"","frontmatter":{},"headers":[],"relativePath":"ageratum/26.1/packs/bindings.md","filePath":"ageratum/26.1/packs/bindings.md"}'),n={name:"ageratum/26.1/packs/bindings.md"};function d(r,e,c,o,l,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="按物品组件进入对应文章" tabindex="-1">按物品组件进入对应文章 <a class="header-anchor" href="#按物品组件进入对应文章" aria-label="Permalink to &quot;按物品组件进入对应文章&quot;">​</a></h1><p>同一个物品可能有好几种用法。想让受损铁镐专门跳转到维修页，可以在绑定里加上 <code>minecraft:damage</code>。下面这个例子只匹配损耗值为 12 的铁镐，物品栏里这把镐上的附魔、自定义名称等其他组件不受影响。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">navigation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  title: 维修示例</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">guide:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  items:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - &#39;minecraft:iron_pickaxe{&quot;minecraft:damage&quot;:12}&#39;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 维修示例</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">这把镐已经消耗了 12 点耐久。请用铁锭在铁砧上修理。</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段或写法</th><th>类型</th><th>读取规则</th></tr></thead><tbody><tr><td><code>guide.items</code>、<code>items</code></td><td>字符串或字符串列表</td><td>可选。每项写一个绑定规则。</td></tr><tr><td><code>guide.item</code>、<code>guide.item_id</code>、<code>item</code>、<code>item_id</code></td><td>字符串</td><td>单条绑定形式。</td></tr><tr><td><code>namespace:item</code>、<code>namespace:item{}</code></td><td>物品 ID</td><td>两者只检查物品。</td></tr><tr><td>ID 后的 <code>{…}</code></td><td>组件对象文本</td><td>按实际堆栈编码后的数据作子集匹配。先尝试 JSON，解析失败时可尝试 SNBT。</td></tr></tbody></table><p>解析器按 <code>guide.items</code>、<code>guide.item</code>、<code>guide.item_id</code>、<code>items</code>、<code>item</code>、<code>item_id</code> 的顺序读取第一组有效配置，字段之间不会合并。匹配组件对象时，物品只需包含要求的键即可；匹配数组时，要求的元素必须按原顺序出现，中间可以夹着其他元素；数值按数值大小比较。空物品栈、ID 不符或无法解码的条件都不会匹配。<a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/GuideItemBinding.java" target="_blank" rel="noreferrer">绑定解析与匹配</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/MDDocument.java" target="_blank" rel="noreferrer">字段优先级</a></p><p>拿着目标物品执行 <code>/ageratum item</code>，可以查看它的物品 ID 以及相对默认状态发生变化的组件。在背包里把鼠标悬停在物品上，按住“寻思”键（默认 W，默认按住 750 毫秒）就能跳转。如果多个页面同时匹配，会先选当前语言，没有候选再选英文，最后才纳入其他语言。同一语言组内，声明的组件约束越具体越优先：对象每个键加一分，基本值各加一分，数组累加成员分数，只写物品 ID 得零分。同一页有多条规则时取最高分，同分再按页面资源 ID 的字典序挑第一项。<a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/command/AgeratumCommand.java" target="_blank" rel="noreferrer">命令实现</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/GuideDocumentCache.java" target="_blank" rel="noreferrer">缓存选择</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/AgeratumClientConfig.java" target="_blank" rel="noreferrer">按键设置</a></p>`,6)])])}const g=a(n,[["render",d]]);export{m as __pageData,g as default};
